// The shape x solver grid.
//
// The point of the refactor is that shapes and solvers are independent: a shape declares what it can
// do by which interfaces it implements, and every solver accepting those interfaces works with it
// unchanged. This file is what makes that claim true rather than aspirational -- it drives each shape
// through each solver it qualifies for, so a new shape is one struct plus one row here.
//
//   shape       Distance  Estimate(RANSAC)  Refit(IRLS)  Pack/Unpack(NLS)
//   Plane          y            y               y              -
//   Line3          y            y               y              -
//   Sphere3        y            y               y              -
//   Cylinder       y            y               -              y
//   Cone           y            y               -              y
//   Torus          y            y               -              y
//   Capsule        y            y               -              y
//
// Cylinder/cone/torus/capsule have no closed-form WEIGHTED fit, so they are estimable and parametric
// but not IRLS-refittable -- the interfaces say so, and the compiler enforces it. That asymmetry is
// the design working, not a gap.
public class floatFitShapeSolverTests
{
    static double Tol => 5e-3;

    static NativeArray<float3> PlaneCloud(int n, float tilt)
    {
        var pts = new NativeArray<float3>(n * n, Allocator.Temp);
        int k = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                pts[k++] = new float3((float)i, (float)j, tilt * (float)i);
        return pts;
    }

    static NativeArray<float3> SphereCloud(float3 c, double r, int nu, int nv)
    {
        var pts = new NativeArray<float3>(nu * nv, Allocator.Temp);
        int k = 0;
        for (int i = 0; i < nu; i++)
            for (int j = 0; j < nv; j++)
            {
                double u = math.PI_DBL * (i + 0.5) / nu, v = 2.0 * math.PI_DBL * j / nv;
                pts[k++] = new float3((float)((double)c.x + r * math.sin(u) * math.cos(v)),
                                       (float)((double)c.y + r * math.sin(u) * math.sin(v)),
                                       (float)((double)c.z + r * math.cos(u)));
            }
        return pts;
    }

    static NativeArray<float3> CylinderCloud(double rad, int nz, int nth)
    {
        var pts = new NativeArray<float3>(nz * nth, Allocator.Temp);
        int k = 0;
        for (int i = 0; i < nz; i++)
            for (int j = 0; j < nth; j++)
            {
                double z = -3.0 + 6.0 * i / (nz - 1.0), th = 2.0 * math.PI_DBL * j / nth;
                pts[k++] = new float3((float)(rad * math.cos(th)), (float)(rad * math.sin(th)), (float)z);
            }
        return pts;
    }

